276	
277	            Optional<TransLogClient.TransLogQuoteResponse> quote = transLogClient.getQuote(zipCode, weightGrams, service);
278	
279	            if (quote.isEmpty()) {
280	                throw new OrderServiceException("SHIPPING_METHOD_UNAVAILABLE",
281	                        "Shipping method not available for this location", HttpStatus.UNPROCESSABLE_ENTITY);
282	            }
283	
284	            TransLogClient.TransLogQuoteResponse response = quote.get();
285	            BigDecimal cost = new BigDecimal(response.getPriceCents()).divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
286	            int days = (int) Math.ceil(response.getEtaHours() / 24.0);
287	
288	            if (region == Region.NORTH) {
289	                days += NORTH_EXTRA_DAYS;
290	            } else if (region == Region.NORTHEAST) {
291	                days += NORTHEAST_EXTRA_DAYS;
292	            }
293	
294	            return new ShippingInfo(cost, days);
295	        }
296	
297	        throw new OrderServiceException("INVALID_SHIPPING_METHOD", "Invalid shipping method", HttpStatus.UNPROCESSABLE_ENTITY);
298	    }
299	
300	    private BigDecimal calculateTotalWeight(List<CheckoutSummaryRequest.OrderItemRequest> items,
301	                                           List<Product> products) {
302	        BigDecimal totalWeight = BigDecimal.ZERO;
303	
304	        for (int i = 0; i < items.size(); i++) {
305	            BigDecimal itemWeight = products.get(i).getWeightKg()
306	                    .multiply(new BigDecimal(items.get(i).getQuantity()));
307	            totalWeight = totalWeight.add(itemWeight);
308	        }
309	
310	        return totalWeight;
311	    }
312	
313	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
314	        BigDecimal percentage;
315	        BigDecimal limit = null;
316	
317	        switch (region) {
318	            case SOUTHEAST, SOUTH -> percentage = new BigDecimal("0.01");
319	            case MIDWEST -> percentage = new BigDecimal("0.015");
320	            case NORTH -> {
321	                percentage = new BigDecimal("0.025");
322	                limit = new BigDecimal("30.00");
323	            }
324	            case NORTHEAST -> {
325	                percentage = new BigDecimal("0.02");
326	                limit = new BigDecimal("30.00");
327	            }
328	            default -> percentage = BigDecimal.ZERO;
329	        }
330	
331	        BigDecimal insurance = CurrencyUtils.multiply(productsSubtotal, percentage);
332	
333	        if (limit != null && insurance.compareTo(limit) > 0) {
334	            insurance = limit;
335	        }
336	
337	        return insurance;
338	    }
339	
340	    private BigDecimal calculatePaymentAdjustment(BigDecimal subtotal, PaymentMethod method, Integer installments) {
341	        int numInstallments = installments != null ? installments : 1;
342	
343	        if (method == PaymentMethod.PIX) {
344	            return CurrencyUtils.multiply(subtotal, PIX_DISCOUNT_PERCENT.negate());
345	        } else if (method == PaymentMethod.BANK_SLIP) {
346	            return BANK_SLIP_FEE;
347	        } else if (method == PaymentMethod.CREDIT_CARD) {
348	            if (numInstallments <= 3) {
349	                return BigDecimal.ZERO;
350	            }
351	            BigDecimal monthlyRate = new BigDecimal("0.0199");
352	            BigDecimal numerator = monthlyRate;
353	            BigDecimal denominator = BigDecimal.ONE.subtract(
354	                    BigDecimal.ONE.add(monthlyRate).pow(-numInstallments)
355	            );
356	            BigDecimal installmentValue = subtotal.multiply(numerator.divide(denominator, 10, RoundingMode.HALF_EVEN));
357	            installmentValue = CurrencyUtils.roundToCents(installmentValue);
358	            BigDecimal totalValue = installmentValue.multiply(new BigDecimal(numInstallments));
359	            return CurrencyUtils.subtract(totalValue, subtotal);
360	        }
361	
362	        return BigDecimal.ZERO;
363	    }
364	
365	    private BigDecimal calculateInstallmentAmount(BigDecimal total, Integer installments) {
366	        int numInstallments = installments != null && installments > 0 ? installments : 1;
367	        return CurrencyUtils.divide(total, new BigDecimal(numInstallments));
368	    }
369	
370	    private BigDecimal calculateNextPurchaseCredit(ClubTier tier, BigDecimal productsSubtotal) {
371	        if (tier == ClubTier.BRONZE) {
372	            return BigDecimal.ZERO;
373	        } else if (tier == ClubTier.SILVER) {
374	            return CurrencyUtils.multiply(productsSubtotal, new BigDecimal("0.02"));
375	        } else if (tier == ClubTier.GOLD) {
376	            return CurrencyUtils.multiply(productsSubtotal, new BigDecimal("0.05"));
377	        }
378	
379	        return BigDecimal.ZERO;
380	    }
381	
382	    private static class ShippingInfo {
383	        BigDecimal cost;
384	        Integer days;
385	
386	        ShippingInfo(BigDecimal cost, Integer days) {
387	            this.cost = cost;
388	            this.days = days;
389	        }
390	    }
391	}

