    78	import java.math.BigDecimal;
    79	import java.math.RoundingMode;
    80	
    81	public class CurrencyUtils {
    82	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    83	
    84	    public static BigDecimal roundToCents(BigDecimal value) {
    85	        if (value == null) {
    86	            return BigDecimal.ZERO;
    87	        }
    88	        return value.setScale(2, ROUNDING_MODE);
    89	    }
    90	
    91	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
    92	        return roundToCents(a.multiply(b));
    93	    }
    94	
    95	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
    96	        return roundToCents(a.divide(b, 10, ROUNDING_MODE));
    97	    }
    98	
    99	    public static BigDecimal add(BigDecimal... values) {
   100	        BigDecimal result = BigDecimal.ZERO;
   101	        for (BigDecimal value : values) {
   102	            if (value != null) {
   103	                result = result.add(value);
   104	            }
   105	        }
   106	        return roundToCents(result);
   107	    }
   108	
   109	    public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
   110	        return roundToCents(a.subtract(b));
   111	    }
   112	}
